/* Khaana — whole-site search.
 *
 * Static site, so there is no server to query: this loads the prebuilt index at
 * data/search-index.json (generated by tools/build-search-index.py) and matches
 * in the browser. Results appear in a panel directly under the box.
 */
(function () {
  'use strict';

  var INDEX_URL = 'data/search-index.json';
  var MAX_RESULTS = 7;

  var input, panel, entries = null, active = -1, loading = false;

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function load() {
    if (entries || loading) return Promise.resolve();
    loading = true;
    return fetch(INDEX_URL)
      .then(function (r) { return r.json(); })
      .then(function (d) { entries = d.entries || []; prepare(); })
      .catch(function () { entries = []; })
      .then(function () { loading = false; });
  }

  /* Normalising 560 entries costs one pass over the whole index, so it happens
     here — load() runs on focus, before the first keystroke — rather than
     inside the matcher where every keystroke would pay for it again. */
  function prepare() {
    entries.forEach(function (e) {
      e._doc = window.KhaanaMatch.prepare({
        title: e.title,
        // The snippet is the entry's own summary, so a hit here means far more
        // than one somewhere in the body.
        strong: [e.snippet || '', e.region || ''].join(' '),
        body: e.text || ''
      });
    });
  }

  /* Ranking still favours where the match lands — a title hit beats a passing
     mention in body copy, so "goan" surfaces the Goan page rather than every
     recipe naming it in a step. What changed is that each word of the query is
     matched on its own, so order, partial words and alternative spellings all
     work. See assets/js/search-match.js. */
  function search(q) {
    var M = window.KhaanaMatch;
    var toks = M.tokens(q);
    var phrase = M.norm(q);
    if (!toks.length || phrase.length < 2) return [];

    return entries
      .map(function (e) {
        var s = M.score(e._doc, toks, phrase);
        // Nudge recipes above prose pages when scores are otherwise close —
        // someone typing an ingredient usually wants something to cook.
        if (s > 0 && e.kind === 'recipe') s += 5;
        // One bare word that names a region is the exception: "goan" wants the
        // Goan page, which leads on to its dishes. "goan fish" wants a recipe,
        // and two words no longer trigger this.
        if (s > 0 && e.kind === 'cuisine' && toks.length === 1 &&
            e._doc.title.indexOf(phrase) === 0) s += 30;
        return { e: e, s: s };
      })
      .filter(function (r) { return r.s > 0; })
      // Equal scores: the shorter title is the more specific page.
      .sort(function (a, b) { return b.s - a.s || a.e.title.length - b.e.title.length; })
      .slice(0, MAX_RESULTS)
      .map(function (r) { return r.e; });
  }

  var KIND_LABEL = { recipe: 'Recipe', cuisine: 'Region', page: 'Page' };

  function render(list, q) {
    if (!list.length) {
      panel.innerHTML = '<p class="find-empty">Nothing matches &ldquo;' + esc(q) +
        '&rdquo;. Try a dish, an ingredient or a region, or ' +
        '<a href="cook.html">cook from what you have</a>.</p>';
      panel.hidden = false;
      return;
    }
    panel.innerHTML = list.map(function (e, i) {
      return '<a class="find-hit" role="option" id="find-hit-' + i + '" href="' + esc(e.url) + '">' +
        '<span class="find-hit-kind" data-kind="' + esc(e.kind) + '">' +
          esc(KIND_LABEL[e.kind] || e.kind) + '</span>' +
        '<span class="find-hit-body">' +
          '<span class="find-hit-title">' + esc(e.title) +
            (e.region ? ' <em>&middot; ' + esc(e.region) + '</em>' : '') + '</span>' +
          '<span class="find-hit-snip">' + esc(e.snippet || '') + '</span>' +
        '</span></a>';
    }).join('');
    panel.hidden = false;
    active = -1;
  }

  function close() { panel.hidden = true; active = -1; }

  function hits() {
    return Array.prototype.slice.call(panel.querySelectorAll('.find-hit'));
  }

  function move(delta) {
    var list = hits();
    if (!list.length) return;
    if (active >= 0 && list[active]) list[active].classList.remove('is-active');
    active = (active + delta + list.length) % list.length;
    list[active].classList.add('is-active');
    input.setAttribute('aria-activedescendant', list[active].id);
    list[active].scrollIntoView({ block: 'nearest' });
  }

  function onInput() {
    var q = input.value;
    if (q.trim().length < 2) { close(); return; }
    load().then(function () { render(search(q), q); });
  }

  document.addEventListener('DOMContentLoaded', function () {
    input = document.getElementById('site-search');
    panel = document.getElementById('site-search-results');
    if (!input || !panel) return;

    input.addEventListener('focus', load);
    input.addEventListener('input', onInput);

    input.addEventListener('keydown', function (ev) {
      if (ev.key === 'ArrowDown') { ev.preventDefault(); move(1); }
      else if (ev.key === 'ArrowUp') { ev.preventDefault(); move(-1); }
      else if (ev.key === 'Enter') {
        var list = hits();
        if (active >= 0 && list[active]) { ev.preventDefault(); window.location = list[active].href; }
      } else if (ev.key === 'Escape') { close(); input.blur(); }
    });

    document.addEventListener('click', function (ev) {
      if (!panel.contains(ev.target) && ev.target !== input) close();
    });
  });
})();
